export const BODY: string = "\n<p>النص يحوّل الصورة إلى رسالة. التعليق يشرح ما تُظهره الصورة، والعنوان يمنحها اسمًا، والاقتباس يمنحها صوتًا.</p>\n<p>إضافة نص إلى صورة مهارة بسيطة لها استخدامات كثيرة: منشورات التواصل والميمز والعروض التقديمية ووسوم المنتجات ولقطات الشاشة المشروحة تعتمد عليها كلها.</p>\n<p>يشرح هذا الدليل كيف تضيف النص بشكل صحيح. يغطي الخطوط والحجم واللون والتباين والحدود والموضع، والأخطاء التي تجعل النص غير مقروء.</p>\n<h2 id=\"what-text-on-image-does\">ماذا يفعل النص على الصورة؟</h2>\n<p>النص يضيف معنى لا تستطيع الصورة وحدها حمله. صورة جبل هي مجرد جبل، لكن نفس الصورة مع تعليق تصبح ذكرى أو نكتة أو دعوة.</p>\n<p>النص يضيف سياقًا أيضًا. التاريخ أو المكان أو الاسم المكتوب على الصورة يخبر المشاهد بما ينظر إليه دون شرح منفصل. وللأعمال، النص على الصورة هو وسّم: سعر أو خصم أو تاريخ حدث.</p>\n<h2 id=\"captions-vs-watermarks\">التعليقات والعناوين والعلامات المائية أعمال مختلفة</h2>\n<p>التعليق يشرح الصورة. يقع قرب الموضوع ويسهل قراءته، وهو مخصص ليراه كل من ينظر إلى الصورة.</p>\n<p>العنوان يسمّي الصورة. يكون عادة أكبر وأجرأ من التعليق ويحدد نبرة كل شيء آخر. أما العلامة المائية فتحمي الصورة: تحدد المالك وغالبًا ما تكون شبه شفافة لتبقى بعد النسخ وإعادة النشر.</p>\n<h2 id=\"fonts-explained\">الخطوط: كيف تختار خطًا مناسبًا</h2>\n<p>الخط يحدد مزاج النص قبل أن يقرأ أحد الكلمات. الخط العريض بلا زخارف يبدو عصريًا ومباشرًا، بينما خط الزخارف يبدو كلاسيكيًا ورسميًا.</p>\n<p>اختر خطًا يطابق الصورة. الميمز المرح يحتاج خطًا عريضًا سميكًا، وصورة الزفاف تحتاج شيئًا أنيقًا خفيفًا. والتزم بخط أو خطين في الصورة الواحدة، لأن خلط خطوط كثيرة يبدو فوضويًا.</p>\n<h2 id=\"text-size-scaling\">حجم النص: الصور الصغيرة مقابل الصور الكبيرة</h2>\n<p>يُحدد حجم النص كنسبة مئوية من الصورة، من 2 بالمئة إلى 22 بالمئة. هذا يعني أن الإعداد نفسه يبدو متسقًا في الصورة المصغرة الصغيرة وفي صورة الكاميرا الضخمة.</p>\n<p>للعنوان، استخدم حجمًا أكبر قرب الطرف الأعلى من النطاق. وللتعليق أو سطر الإسناد، استخدم حجمًا أصغر يبقى مقروءًا دون أن يهيمن على الصورة. وراجع النص بالحجم الحقيقي الذي ستشاركه به.</p>\n<h2 id=\"colour-and-contrast\">اللون والتباين: كيف تجعل النص مقروءًا</h2>\n<p>النص الأبيض يعمل على الخلفيات الداكنة والنص الأسود على الخلفيات الفاتحة، لكن معظم الصور تحتوي على الاثنين معًا. لون واحد سيختفي دائمًا في مكان ما من الصورة.</p>\n<p>التباين هو ما يجعل النص مقروءًا، وليس اللون وحده. ضع النص فوق أنعم جزء في الصورة، مثل سماء صافية أو جدار فارغ. وعندما لا توجد منطقة ناعمة، أضف لوحة خلفية شبه شفافة داكنة خلف النص الأبيض.</p>\n<h2 id=\"outline-and-shadow\">الحدود والظلال</h2>\n<p>الحد هو إطار مرسوم حول كل حرف. الحد الداكن الرفيع حول النص الأبيض يبقيه مقروءًا في السماء الساطعة، ولهذا يستخدمه الميمز.</p>\n<p>الظل يرفع النص عن الخلفية. يضيف حافة داكنة ناعمة خلف الحروف تساعدها على البروز دون المظهر القاسي للحد. استخدم أحدهما لا كليهما بقوة كاملة، لأن الجمع بينهما يجعل النص يبدو مزدحمًا.</p>\n<h2 id=\"positioning-and-layers\">الموضع والطبقات</h2>\n<p>يمكن نقل طبقات النص إلى أي مكان في الصورة. اسحب الطبقة لوضعها، وتتيح الأداة اختيار كل طبقة على حدة عندما يكون لديك عدة طبقات.</p>\n<p>الأعلى والأسفل هما الموضعان الكلاسيكيان للتعليقات. العنوان في الأعلى والخاتمة في الأسفل هو صيغة الميمز، ويعمل لأن العين تقرأ من الأعلى إلى الأسفل. وأبقِ النص بعيدًا عن الحواف.</p>\n<h2 id=\"rotating-text\">كيف تدوّر النص لإضفاء تأثير</h2>\n<p>يمكن إمالة النص بزوايا مخصصة، ما يضيف طاقة إلى التصميم. العنوان المائل قليلًا يبدو ديناميكيًا، بينما النص المستقيم يبدو هادئًا ورسميًا.</p>\n<p>استخدم التدوير باعتدال. ميل صغير ببضع درجات يضيف طابعًا، بينما الزاوية الحادة تجعل النص صعب القراءة ويبدو كخطأ. النص المائل يناسب الملصقات والرسوم الاجتماعية، ويسيء للتعليمات والوسوم.</p>\n<h2 id=\"multi-line-text\">تعليقات متعددة الأسطر</h2>\n<p>الضغط على Enter داخل محتوى النص ينشئ سطرًا جديدًا. هذا يتيح كتابة تعليق يمتد على سطرين أو ثلاثة دون إنشاء طبقة منفصلة لكل سطر.</p>\n<p>أبقِ الأسطر قصيرة. التعليق الذي يمتد عبر عرض الصورة كاملًا صعب القراءة، بينما الأسطر القصيرة المتمركزة على الموضوع سهلة المتابعة. واقطع الأسطر عند الوقفات الطبيعية في الجملة.</p>\n<h2 id=\"memes\">كيف تصنع الميمز</h2>\n<p>الميمز صورة مع تعليق قصير مضحك، عادة بنص أبيض وحد داكن سميك في الأعلى والأسفل. الصيغة بسيطة، وهذه البساطة هي جوهرها.</p>\n<p>أبقِ النص قصيرًا. ميمز بفقرة نصية ليس مضحكًا، لأن لا أحد يقرأ فقرة في صورة نكتة. سطر في الأعلى وآخر في الأسفل يكفيان. واستخدم خطًا عريضًا سميكًا يبقى مقروءًا في الأحجام الصغيرة.</p>\n<h2 id=\"quotes-and-titles\">الاقتباسات والعناوين والرسوم الاجتماعية</h2>\n<p>الاقتباس على صورة صيغة اجتماعية شائعة. يكون النص عادة كبيرًا ومتمركزًا وموضوعًا فوق منطقة ناعمة من الصورة أو خلفية معتمة.</p>\n<p>أبقِ الاقتباسات قصيرة. جملة واحدة تعمل أفضل بكثير من فقرة، لأن الصورة والكلمات تتشاركان المساحة. وللعناوين، استخدم حجمًا أكبر وخطًا أجرأ من التعليقات، ليكون العنوان أول ما تلتقطه العين.</p>\n<h2 id=\"annotations\">الشروح والوسوم</h2>\n<p>الشروح تشرح أجزاء الصورة. وسم بسهم أو خطوة مرقمة أو ملاحظة قصيرة يحوّل لقطة الشاشة إلى تعليمات.</p>\n<p>أبقِ الشروح قصيرة وضعها قرب ما تصفه. الوسم البعيد عن موضوعه يربك المشاهد، بينما الوسم بجانبه مباشرة يكون واضحًا. واستخدم أسلوبًا متسقًا لكل الشروح في الصورة الواحدة.</p>\n<h2 id=\"formats-and-export\">الصيغ والتصدير</h2>\n<p>تقبل الأداة صيغ الصور الشائعة، بما فيها JPG وPNG وWebP وHEIC، بملفات حتى 20 ميغابايت. ويمكنك التصدير بصيغة JPG أو PNG أو WebP حسب حاجتك.</p>\n<p>التصدير بصيغة PNG أو WebP يحافظ على الشفافية في الصورة الأساسية. أما للصور ذات النص، فـJPG بجودة عالية يعمل جيدًا، لكن أبقِ الجودة عالية لأن حواف النص قد تلين قليلًا مع ضغط JPG.</p>\n<h2 id=\"privacy-local-processing\">الخصوصية: إضافة النص دون رفع</h2>\n<p>كل تحرير النص يحدث في متصفحك. صورك لا تُرفع أبدًا إلى خادم، وهذا مهم عندما تكون الصور شخصية أو عائلية أو لقطات عمل.</p>\n<p>هذه ميزة حقيقية أمام محررات السحابة. كما تزيل الأداة بيانات GPS من EXIF عند التصدير. واحتفظ بالصورة الأصلية دون نص، لأن النص المدمج في التصدير لا يمكن إزالته من ذلك الملف.</p>\n<h2 id=\"common-mistakes\">الأخطاء الشائعة عند إضافة النص</h2>\n<p>الخطأ الأكثر شيوعًا هو نص صغير جدًا. التعليق الذي يبدو جيدًا بالحجم الكامل قد يكون غير مقروء في خلاصة اجتماعية، حيث تُعرض الصورة أصغر بكثير.</p>\n<p>من الأخطاء الأخرى التباين الضعيف والكتابة المفرطة. فقرة نصية على صورة تخفي الصورة وتُرهق المشاهد، بينما كلمات قليلة مختارة بعناية تؤدي العمل أفضل. ولا تضع نصًا حيث ستقصه المنصة.</p>\n<h2 id=\"text-on-product-photos\">النص على صور المنتجات</h2>\n<p>صور المنتجات تحمل غالبًا نصًا قصيرًا: سعر أو خصم أو ميزة. يجب أن يكون النص كبيرًا وعريضًا وموضوعًا حيث لا يغطي المنتج نفسه.</p>\n<p>ضع السعر أو العرض في زاوية لا في المنتصف. وسم الزاوية يُبقي المنتج ظاهرًا، بينما الوسم المركزي يخفي ما تبيعه. واستخدم أسلوبًا متسقًا في كل كتالوجك، وأبقِ النص قصيرًا: سعر وكلمة واحدة مثل عرض أو جديد تكفيان.</p>\n<p>وللخطوات التفصيلية، راجع <a href=\"/ar/blog/kayfiyya-idafa-nass-ila-as-sura/\">كيف تضيف نصًا إلى صورة</a>. ولقواعد المقروئية، اقرأ <a href=\"/ar/blog/nasaih-li-qiraat-an-nass-ala-as-suwar/\">النص على الصور: الخطوط والتباين والمقروئية</a>. ولوضع علامة ملكية بدل الرسالة، جرّب <a href=\"/ar/idafa-alama-maiyya/\">أداة العلامة المائية</a> أو <a href=\"/ar/idafa-nass-ila-as-sura/\">أداة إضافة نص إلى صورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما أفضل خط للنص على صورة؟","answer":"الخط العريض بلا زخارف هو الخيار الآمن لمعظم الصور، لأنه يبقى مقروءًا في الأحجام الصغيرة والخلفيات المزدحمة. خطوط الزخارف تناسب الصور الرسمية مثل صور الزفاف، والخطوط المزخرفة تناسب التصاميم المرحة."},{"question":"كيف أجعل النص الأبيض مقروءًا على صورة ساطعة؟","answer":"أضف حدًا داكنًا أو ظلًا حول الحروف ليبقى ظاهرًا في المناطق الساطعة. وضع النص فوق أظلم جزء في الصورة يساعد أيضًا. اللوحة الداكنة شبه الشفافة خلف النص الأبيض تجعله مقروءًا في أي مكان."},{"question":"هل يمكنني إضافة أكثر من سطر نص إلى صورة؟","answer":"نعم، اضغط Enter داخل محتوى النص لإنشاء سطر جديد في الطبقة نفسها، أو أضف طبقة منفصلة لكل سطر. الطبقات المنفصلة تتيح وضع تعليق علوي وآخر سفلي بشكل مستقل."},{"question":"ما الفرق بين إضافة نص ووضع علامة مائية؟","answer":"إضافة النص تنشئ تعليقًا أو عنوانًا أو شرحًا مخصصًا ليقرأه الجميع. وضع العلامة المائية يضيف علامة ملكية شبه شفافة مخصصة للبقاء بعد النسخ. استخدم أداة النص للرسائل وأداة العلامة المائية للحماية."},{"question":"ما حجم النص المناسب لصورة على وسائل التواصل؟","answer":"كبير بما يكفي ليُقرأ في معاينة خلاصة صغيرة، لا بالحجم الكامل فقط. العناوين تحتاج حجمًا قرب الطرف الأعلى من نطاق 2 إلى 22 بالمئة، بينما يمكن أن تكون التعليقات أصغر."},{"question":"هل إضافة نص إلى صورة تزيل بيانات موقعها؟","answer":"نعم، التصدير من الأداة يزيل وسوم GPS من EXIF في الملف. النص يندمج في الصورة وسجل الموقع يُزال في نفس الخطوة. احتفظ بالملف الأصلي إذا أردت الحفاظ على هذه البيانات."}];
